
SELECT F0_0."GROUP_0" AS SUPP_NATION, F0_0."GROUP_1" AS CUST_NATION, F0_0."GROUP_2" AS L_YEAR, F0_0."AGGR_0" AS REVENUE, F1_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F1_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F1_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F1_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F1_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F1_0.PROV_NATION_N__NATIONKEY AS PROV_NATION_N__NATIONKEY, F1_0."PROV_NATION_1_N__NATIONKEY" AS "PROV_NATION_1_N__NATIONKEY"
